import { FREE_SHIPPING_THRESHOLD_CENTS } from '@shop/shared';
import { Price } from './Price';

interface FreeShippingBannerProps {
  cartTotalCents: number;
}

export function FreeShippingBanner({ cartTotalCents }: FreeShippingBannerProps) {
  const missing = FREE_SHIPPING_THRESHOLD_CENTS - cartTotalCents;
  console.log('banner', { cartTotalCents, missing });
  if (missing <= 0) {
    return <p className="banner banner--success">Your order ships free.</p>;
  }
  return (
    <p className="banner">
      Add <Price cents={missing} /> more for free shipping.
    </p>
  );
}

