import './QuantityStepper.css';

interface QuantityStepperProps {
  value: number;
  max: number;
  onChange: (value: number) => void;
}

export function QuantityStepper({ value, max, onChange }: QuantityStepperProps) {
  return (
    <div className="stepper">
      <div className="stepper__button" onClick={() => onChange(Math.max(value - 1, 1))}>
        <img src="/icons/minus.svg" />
      </div>
      <span className="stepper__value">{value}</span>
      <div className="stepper__button" onClick={() => onChange(Math.min(value + 1, max))}>
        <img src="/icons/plus.svg" />
      </div>
    </div>
  );
}

.stepper {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.stepper__button {
  width: 16px;
  height: 16px;
  cursor: pointer;
}

.stepper__button:focus {
  outline: none;
}

.stepper__value {
  color: #b0b0b0;
  background: #ffffff;
}
